  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider  = \"postgresql\"\n  url       = env(\"DATABASE_URL\")\n  directUrl = env(\"DIRECT_URL\")\n}\n\n// ─────────────────────────────────────────────\n// ENUMS\n// ─────────────────────────────────────────────\n\nenum TimeOfDay {\n  MORNING // Matin\n  MIDDAY // Midi\n  EVENING // Soir\n  BEDTIME // Coucher\n}\n\nenum DoseStatus {\n  PENDING // En attente\n  TAKEN // Pris\n  MISSED // Manqué\n  SKIPPED // Not needed (e.g. Doliprane \"si douleur\")\n}\n\nenum PrescriptionStatus {\n  DRAFT // Scanned, waiting for caregiver validation\n  ACTIVE // Ordonnance active\n  EXPIRED\n}\n\nenum RefillStatus {\n  PLANNED // \"Je m'en occupe\" – Jeudi matin\n  DONE\n}\n\n// ─────────────────────────────────────────────\n// MODELS\n// ─────────────────────────────────────────────\n\nmodel Patient {\n  id                Int                @id @default(autoincrement())\n  firstName         String // \"Jeanne\"\n  lastName          String // \"Dupont\"\n  birthDate         DateTime\n  avatarUrl         String?\n  familyMembers     FamilyMember[]\n  prescriptions     Prescription[]\n  medications       Medication[]\n  pushSubscriptions PushSubscription[]\n}\n\nmodel FamilyMember {\n  id                 Int             @id @default(autoincrement())\n  patient            Patient         @relation(fields: [patientId], references: [id])\n  patientId          Int\n  firstName          String // \"Lavanya\"\n  relation           String // \"Ma fille\"\n  phone              String // \"06 12 34 56 78\"\n  avatarUrl          String?\n  availability       String? // \"Disponible de suite\"\n  isPrimaryCaregiver Boolean         @default(false) // receives \"J'ai pris\" confirmations\n  callOrder          Int             @default(0) // order on the Urgence screen\n  refillRequests     RefillRequest[]\n  confirmedDoses     DoseEvent[]\n}\n\nmodel Prescription {\n  id              Int                @id @default(autoincrement())\n  patient         Patient            @relation(fields: [patientId], references: [id])\n  patientId       Int\n  doctorName      String // \"Dr. Vasseur\"\n  doctorSpecialty String? // \"Médecin généraliste\"\n  clinicName      String? // \"Cabinet Médical Saint-Louis\"\n  clinicPhone     String?\n  pharmacyName    String? // \"Pharmacie du Parc\"\n  issuedAt        DateTime?\n  imageUrl        String? // scanned prescription photo\n  ocrConfidence   Float? // 98.4\n  status          PrescriptionStatus @default(DRAFT)\n  createdAt       DateTime           @default(now())\n  medications     Medication[]\n}\n\nmodel Medication {\n  id                    Int             @id @default(autoincrement())\n  patient               Patient         @relation(fields: [patientId], references: [id])\n  patientId             Int\n  prescription          Prescription?   @relation(fields: [prescriptionId], references: [id])\n  prescriptionId        Int?\n  name                  String // \"Metformine\"\n  strength              String // \"500 mg\"\n  activeIngredient      String? // \"Chlorhydrate de metformine\"\n  purpose               String? // \"Régulation glycémique\"\n  form                  String // \"Comprimé\", \"Sachet\", \"Comprimé effervescent\"\n  doseQuantity          Float           @default(1)\n  doseUnit              String // \"comprimé\", \"sachet\"\n  instruction           String // \"avec un verre d'eau\"\n  mealInstruction       String? // \"Au milieu du déjeuner\"\n  appearance            String? // \"Sachet en papier blanc\"\n  pillboxSection        String? // \"Section 1\"\n  asNeeded              Boolean         @default(false) // Doliprane \"si douleur\"\n  maxPerDay             Int? // 3\n  stockDoses            Int // 21\n  lowStockAlert         Boolean         @default(true)\n  lowStockThresholdDays Int             @default(7)\n  renewalDate           DateTime?\n  matchedInDatabase     Boolean         @default(false)\n  isActive              Boolean         @default(true)\n  slots                 ScheduleSlot[]\n  refillRequests        RefillRequest[]\n}\n\nmodel ScheduleSlot {\n  id           Int         @id @default(autoincrement())\n  medication   Medication  @relation(fields: [medicationId], references: [id])\n  medicationId Int\n  timeOfDay    TimeOfDay // MIDDAY\n  time         String // \"12:30\"\n  isActive     Boolean     @default(true) // false = intake time removed; kept for dose history\n  doses        DoseEvent[]\n}\n\nmodel DoseEvent {\n  id            Int           @id @default(autoincrement())\n  slot          ScheduleSlot  @relation(fields: [slotId], references: [id])\n  slotId        Int\n  scheduledAt   DateTime // exact date + time of this dose\n  status        DoseStatus    @default(PENDING)\n  takenAt       DateTime? // \"Pris à 08:14\"\n  snoozedUntil  DateTime? // \"Remind me in 15 minutes\"\n  snoozeCount   Int           @default(0) // 3 snoozes, then a last reminder, then MISSED\n  remindedAt    DateTime? // last push notification sent for this dose\n  confirmedBy   FamilyMember? @relation(fields: [confirmedById], references: [id])\n  confirmedById Int? // null = Jeanne confirmed herself; set = family \"Mark done\"\n\n  @@unique([slotId, scheduledAt])\n}\n\nmodel RefillRequest {\n  id             Int          @id @default(autoincrement())\n  medication     Medication   @relation(fields: [medicationId], references: [id])\n  medicationId   Int\n  familyMember   FamilyMember @relation(fields: [familyMemberId], references: [id])\n  familyMemberId Int\n  plannedFor     String // \"Jeudi matin\"\n  status         RefillStatus @default(PLANNED)\n  createdAt      DateTime     @default(now())\n}\n\n// A device (Jeanne's tablet) that receives medication reminders by Web Push,\n// even when the browser is closed or the screen is locked.\nmodel PushSubscription {\n  id        Int      @id @default(autoincrement())\n  patient   Patient  @relation(fields: [patientId], references: [id])\n  patientId Int\n  endpoint  String   @unique // push service URL for this browser\n  p256dh    String\n  auth      String\n  createdAt DateTime @default(now())\n}\n",
